using System;using System.IO;using System.Linq;using System.Text.Json;using System.Text.Json.Nodes;using System.Collections.Generic;using System.Reflection;using Sdt.Core;using Sdt.Core.Battle;
class Audit {
 sealed class Host:BattleHost { public int Hp{get;set;}=30;public int MaxHp=>60;public int Atk=>4;public int SpellPower=>2;public string MyClass=>null;public string CharacterId=>"wu";public IReadOnlyList<OwnedCard> OwnedCards{get;set;}=Array.Empty<OwnedCard>();public void Log(string text,string kind=null){}public void Heal(int n){Hp=Math.Min(MaxHp,Hp+n);}public void OnBattleEnd(BattleResult r){} }
 static RuleValue Rule(JsonObject data){var r=new RuleValue();foreach(var p in data)r.Values[p.Key]=Value(p.Value);return r;}
 static object Value(JsonNode v){if(v==null)return null;if(v is JsonObject o)return Rule(o);if(v is JsonArray a)return a.Select(Value).ToArray();var r=(JsonValue)v;if(r.TryGetValue<int>(out var n))return n;if(r.TryGetValue<bool>(out var b))return b;if(r.TryGetValue<string>(out var s))return s;return r.GetValue<double>();}
 static object Field(BattleSession b,string n)=>typeof(BattleSession).GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(b);
 static void Main(){CardLibrary.Init(()=>CardDatabase.All);var rows=JsonNode.Parse(File.ReadAllText("source-results.json")).AsArray();var result=new List<object>();foreach(var row in rows){var owned=row["input"].AsArray().Select(n=>{var c=n["card"].Deserialize<CardDef>(new JsonSerializerOptions{IncludeFields=true});c.rules=n["card"]["rules"] is JsonObject r?Rule(r):null;return new OwnedCard{uid=(string)n["uid"],card=c};}).ToArray();var b=new BattleSession();b.Start(new BattleStartContext{host=new Host{OwnedCards=owned},rng=new Rng(123),isBoss=((string)row["name"]).EndsWith("-boss"),enemies=new[]{new EnemyInput{id="foe",name="目标",hp=100,atk=2}}});var name=(string)row["name"];if(name.EndsWith("-boss")){foreach(var entry in owned)if(entry.card.id!="starter-attack")b.SelectDeckCard(entry.uid);b.ConfirmDeck();var hand=(List<string>)Field(b,"hand");hand.Clear();hand.AddRange(owned.Select(o=>o.uid));((List<string>)Field(b,"drawPile")).RemoveAll(uid=>owned.Any(o=>o.uid==uid));}if(name=="fly"||name=="bleedAmp")((List<BattleFoe>)Field(b,"foes"))[0].status.Set("bleed",3);var command=b.PlayCard("o0",name.StartsWith("grudge")||name=="fly"?0:-1,false);var costs=owned.Skip(1).Select(o=>b.GetEffectiveCost(o.card)).ToArray();if(name=="bleedAmp")command=b.PlayCard("o1",0,false);result.Add(new{name,ok=command.Ok,reason=command.Reason,costs,hand=b.Snapshot.Hand,consumed=(List<string>)Field(b,"consumed"),armor=b.Snapshot.Pdef.Armor,foeHp=b.Snapshot.Foes[0].Hp,energy=b.Snapshot.Energy});b.Retract();}File.WriteAllText("core-results.json",JsonSerializer.Serialize(result,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine(File.ReadAllText("core-results.json"));}
}




